import{_ as a,a as t}from"./chunks/npu_3510_hw_arch_cube.0H1dNCIh.js";import{_ as c,o as _,a as o,b as d}from"./app.BGziXukh.js";const l="/ascendc.github.io/assets/matrix_computation_workflow_c_api.rtnqgO0i.png",m="/ascendc.github.io/assets/mx_matrix_computation_workflow_c_api.DkphH8UG.png",r="/ascendc.github.io/assets/sparse_matrix_computation_workflow_c_api.C1fRHWga.png",p="/ascendc.github.io/assets/conv2d_forward_c_api.B9nWKJC4.png",A=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算","link":"/api/SIMD-API/c_api/cube_compute/cube_compute"},{"text":"概述","link":"/api/SIMD-API/c_api/cube_compute/overview"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_compute/overview.md","filePath":"api/SIMD-API/c_api/cube_compute/overview.md","outlineHeaders":[{"level":2,"title":"矩阵计算概述","slug":"矩阵计算概述","link":"#矩阵计算概述"},{"level":3,"title":"矩阵计算单元","slug":"矩阵计算单元","link":"#矩阵计算单元"},{"level":3,"title":"矩阵计算流程","slug":"矩阵计算流程","link":"#矩阵计算流程"},{"level":4,"title":"普通矩阵计算流程","slug":"普通矩阵计算流程","link":"#普通矩阵计算流程"},{"level":4,"title":"Mx矩阵计算流程","slug":"Mx矩阵计算流程","link":"#Mx矩阵计算流程"},{"level":4,"title":"4选2稀疏矩阵计算流程","slug":"4选2稀疏矩阵计算流程","link":"#4选2稀疏矩阵计算流程"},{"level":4,"title":"Conv2D前向计算流程","slug":"Conv2D前向计算流程","link":"#Conv2D前向计算流程"},{"level":2,"title":"API列表","slug":"API列表","link":"#API列表"},{"level":3,"title":"Mmad计算","slug":"Mmad计算","link":"#Mmad计算"},{"level":3,"title":"Mmad计算辅助配置接口","slug":"Mmad计算辅助配置接口","link":"#Mmad计算辅助配置接口"}],"lastUpdated":1794017913000}'),i={name:"api/SIMD-API/c_api/cube_compute/overview.md"};function s(u,e,f,h,n,b){return _(),o("div",null,[...e[0]||(e[0]=[d('<div><article class="markdown-body"><h1>概述</h1><h2 id="矩阵计算概述">矩阵计算概述<a class="header-anchor" href="#矩阵计算概述">​</a></h2><p>矩阵计算C API提供矩阵乘加及其辅助配置接口。</p><h3 id="矩阵计算单元">矩阵计算单元<a class="header-anchor" href="#矩阵计算单元">​</a></h3><p>Cube计算单元专用于执行矩阵运算，直接访问的专用缓存如下：L0A Buffer用于存储左矩阵，L0B Buffer用于存储右矩阵，L0C Buffer则用于存储初始化累加值和矩阵计算结果。</p><div data-filter="910b,A3,950"><p>下图高亮部分展示了Cube计算单元及其直接访问的专用缓存。</p></div><div data-filter="910b,A3"><p><strong>图1</strong> <a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>矩阵计算单元架构图</p><p><img src="'+a+'" alt title="矩阵计算单元架构图-A2A3"></p></div><div data-filter="950"><p><strong>图2</strong> <a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>矩阵计算单元架构图</p><p><img src="'+t+'" alt title="矩阵计算单元架构图-950"></p></div><p>矩阵计算关联的存储单元为：</p><p><strong>表1</strong> 矩阵计算关联的存储单元</p><table><thead><tr><th>Buffer类型</th><th>说明</th></tr></thead><tbody><tr><td>L0A Buffer</td><td>AI Core内部物理存储单元，通常用于存储矩阵计算的左矩阵。</td></tr><tr><td>L0B Buffer</td><td>AI Core内部物理存储单元，通常用于存储矩阵计算的右矩阵。</td></tr><tr><td>L0C Buffer</td><td>AI Core内部物理存储单元，通常用于存储矩阵计算的结果，以及矩阵累加初始化值。</td></tr><tr><td>L1 Buffer</td><td>AI Core内部物理存储单元，空间相对较大，通常用于缓存矩阵计算的输入数据。矩阵计算的输入一般需要从GM搬运到L1 Buffer，然后分别搬运到L0A Buffer和L0B Buffer。</td></tr><tr><td>Fixpipe Buffer</td><td>AI Core内部物理存储单元，通常用于存储Fixpipe搬运过程中所需的量化参数等数据。</td></tr><tr><td>BiasTable Buffer</td><td>偏置存储，AI Core内部物理存储单元，通常用于存储矩阵计算所需的Bias（偏置）数据。</td></tr></tbody></table><p>各存储单元和流水在计算过程中的配合参见<a href="#%E7%9F%A9%E9%98%B5%E8%AE%A1%E7%AE%97%E6%B5%81%E7%A8%8B">矩阵计算流程</a>；搬入、搬出通路及配套接口分别参见<a href="../cube_datamove/cube_compute_load/cube_compute_load_overall_description.html">矩阵搬入总体说明</a>和<a href="../cube_datamove/cube_compute_store/cube_compute_store_overall_description.html">矩阵搬出总体说明</a>。</p><h3 id="矩阵计算流程">矩阵计算流程<a class="header-anchor" href="#矩阵计算流程">​</a></h3><h4 id="普通矩阵计算流程">普通矩阵计算流程<a class="header-anchor" href="#普通矩阵计算流程">​</a></h4><p>C API针对矩阵计算编程模型提供了数据搬入、矩阵计算和结果搬出接口，分别承载Cube核中各个通路的搬运能力和计算能力，如下图所示：</p><p><strong>图3</strong> 普通矩阵基础计算流程图</p><p><img src="'+l+'" alt title="普通矩阵基础计算流程图"></p><ol><li><p>通过<a href="../cube_datamove/cube_compute_load/asc_copy_gm2l1.html">asc_copy_gm2l1</a>搬入已排布好的A、B矩阵；对于ND输入，使用<a href="../cube_datamove/cube_compute_load/asc_copy_gm2l1_nd2nz.html">asc_copy_gm2l1_nd2nz</a>完成分形转换。Bias和随路量化系数也先搬入L1 Buffer。</p></li><li><p>通过<a href="../cube_datamove/cube_compute_load/asc_copy_l12l0a.html">asc_copy_l12l0a</a>、<a href="../cube_datamove/cube_compute_load/asc_copy_l12l0b.html">asc_copy_l12l0b</a>将A、B分别搬入L0A Buffer、L0B Buffer；根据输入布局选择转置变体。Bias和量化系数分别通过<a href="../cube_datamove/cube_compute_load/asc_copy_l12bt.html">asc_copy_l12bt</a>、<a href="../cube_datamove/cube_compute_load/asc_copy_l12fb.html">asc_copy_l12fb</a>搬入对应Buffer。</p></li><li><p>通过<a href="mmad_compute/asc_mmad.html">asc_mmad</a>计算，输出至L0C Buffer。参数顺序为<code>m, k, n</code>，初次从零计算时设置<code>c_matrix_init_val=true</code>；后续K块累加时设置<code>c_matrix_source=false</code>、<code>c_matrix_init_val=false</code>。Bias初始化的参数说明见<a href="mmad_compute/asc_mmad.html">asc_mmad</a>。</p></li><li><p>通过<a href="../cube_datamove/cube_compute_store/asc_copy_l0c2gm.html">asc_copy_l0c2gm</a>搬出结果，配置随路量化、激活和输出格式。也可搬到L1 Buffer，见<a href="../cube_datamove/cube_compute_store/cube_compute_store_overall_description.html">搬出总体说明</a>。</p></li></ol><div data-filter="950"><h4 id="Mx矩阵计算流程">Mx矩阵计算流程<a class="header-anchor" href="#Mx矩阵计算流程">​</a></h4><p>Mx矩阵计算仅在Ascend 950PR&amp;950DT系列产品型号支持。</p><p>MX矩阵乘法（Microscaling矩阵乘加）为带有量化系数的矩阵乘法，即左矩阵和右矩阵均有对应的量化系数矩阵，左量化系数矩阵scaleA和右量化系数矩阵scaleB。MX矩阵乘法场景中，左量化系数矩阵与左矩阵乘积，右量化系数矩阵与右矩阵乘积，对两个乘积的结果做矩阵乘法。C API通过asc_mmad_mx及独立的数据/系数搬运接口支持MX矩阵计算，如下图所示：</p><p><strong>图4</strong> Mx矩阵基础计算流程图</p><p><img src="'+m+'" alt title="Mx矩阵基础计算流程图"></p><ol><li><p>将A、B和<a href="cube_compute_fractal_intro/aux_cube_fractal_format_details.html">scaleA/scaleB系数矩阵</a>从GM搬到L1 Buffer。A/B数据分形与系数分形不同，分别配置各自的布局、大小和步长。</p></li><li><p>使用<a href="../cube_datamove/cube_compute_load/asc_copy_l12l0a_2d_arch_3510.html">asc_copy_l12l0a</a>、<a href="../cube_datamove/cube_compute_load/asc_copy_l12l0b_2d_arch_3510.html">asc_copy_l12l0b</a>搬入A/B；另外调用<a href="../cube_datamove/cube_compute_load/asc_copy_l12l0a_mx.html">asc_copy_l12l0a_mx</a>、<a href="../cube_datamove/cube_compute_load/asc_copy_l12l0b_mx.html">asc_copy_l12l0b_mx</a>搬入scaleA/scaleB。</p></li><li><p>数据、系数及可选Bias就绪后，通过<a href="mmad_compute/asc_mmad_mx.html">asc_mmad_mx</a>计算并输出至L0C Buffer。</p></li><li><p>使用<a href="../cube_datamove/cube_compute_store/asc_copy_l0c2gm_arch_3510.html">asc_copy_l0c2gm</a>处理并搬出结果。</p></li></ol></div><div data-filter="910b,A3"><h4 id="4选2稀疏矩阵计算流程">4选2稀疏矩阵计算流程<a class="header-anchor" href="#4选2稀疏矩阵计算流程">​</a></h4><p>稀疏矩阵是一种特殊类型的矩阵，即矩阵中包含较多的零元素。4选2结构化稀疏矩阵计算，要求一个连续的4个权重或激活值的组（通常是张量中的一行或一列）中，最多只有2个值为非零，其余2个强制为零。针对Atlas A2系列产品和Atlas A3系列产品，Ascend C针对4选2稀疏矩阵计算编程模型提供了对应sparse类接口，如下图所示：</p><p><strong>图5</strong> 4选2稀疏矩阵基础计算流程图</p><p><img src="'+r+'" alt title="4选2稀疏矩阵基础计算流程图"></p><ol><li><p>首先将原始矩阵B按照固定粒度划分连续4个元素为一组，按照4选2结构化稀疏压缩规则，离线生成对应的压缩矩阵B与<a href="cube_compute_fractal_intro/aux_cube_fractal_format_details.html#4%E9%80%892%E7%A8%80%E7%96%8F%E7%B4%A2%E5%BC%95%E7%9F%A9%E9%98%B5">索引矩阵</a>作为输入。</p></li><li><p>通过asc_copy_gm2l1接口将原始矩阵A、压缩矩阵B、索引矩阵的GM数据搬运到L1 Buffer中（如果存在随路量化，则同样通过asc_copy_gm2l1搬到L1 Buffer中）。</p></li><li><p>通过asc_copy_l12l0a接口将原始矩阵A加载到L0A Buffer，通过<a href="../cube_datamove/cube_compute_load/asc_copy_l12l0b_sparse.html">asc_copy_l12l0b_sparse接口</a>将压缩矩阵B与索引矩阵分别加载到L0B Buffer与内置IDX Buffer上准备计算（如果存在随路量化，则通过asc_copy_l12fb将L1 Buffer中的量化系数数据搬运到Fixpipe Buffer上）。</p></li><li><p>通过asc_mmad_sparse接口对L0A Buffer、L0B Buffer、内置IDX Buffer上面的数据进行4选2稀疏矩阵计算，并输出结果到L0C Buffer上。详细内容请参考<a href="mmad_compute/asc_mmad_sparse.html">asc_mmad_sparse计算</a>。</p></li><li><p>通过asc_copy_l0c2gm接口将L0C Buffer的数据进行处理并搬出到GM，asc_copy_l0c2gm接口可以利用Fixpipe Buffer数据进行如随路量化、Relu等操作。详细内容请参考<a href="../cube_datamove/cube_compute_store/asc_copy_l0c2gm.html">asc_copy_l0c2gm（L0C Buffer到GM数据搬运）</a>。</p></li></ol></div><h4 id="Conv2D前向计算流程">Conv2D前向计算流程<a class="header-anchor" href="#Conv2D前向计算流程">​</a></h4><p>Conv2D前向计算的本质是将卷积运算转换为矩阵乘：先通过img2col（Image to Column）将FeatureMap按卷积核滑动窗口展开为左矩阵A，将Weight作为右矩阵B，再做矩阵乘累加得到输出。与<a href="#%E6%99%AE%E9%80%9A%E7%9F%A9%E9%98%B5%E8%AE%A1%E7%AE%97%E6%B5%81%E7%A8%8B">普通矩阵计算流程</a>的区别在于：A矩阵从GM直接搬入后，由<a href="../cube_datamove/cube_compute_load/asc_copy_l12l0a.html">asc_copy_l12l0a的3D重载</a>在L1 Buffer到L0A Buffer的搬运过程中，根据卷积核尺寸、stride、dilation、padding在线完成img2col空间展开生成，如下图所示：</p><p><strong>图6</strong> Conv2D前向计算流程图</p><p><img src="'+p+'" alt title="Conv2D前向计算流程图"></p><ol><li><p>将FeatureMap和Weight从GM搬入L1 Buffer。FeatureMap按<a href="cube_compute_fractal_intro/key_fractal_format_details.html#nc1hwc0%E6%A0%BC%E5%BC%8F">NC1HWC0格式</a>准备；Weight按后续L0B Buffer搬运所需布局准备。</p></li><li><p>使用<code>asc_copy_l12l0a</code>的3D重载执行img2col，并通过<code>asc_copy_l12l0b</code>搬入Weight。调用前配置FeatureMap属性、重复步长、边界与Padding，具体接口见<a href="../cube_datamove/cube_compute_load/cube_compute_load_overall_description.html">搬入总体说明</a>。</p></li><li><p>使用<a href="mmad_compute/asc_mmad.html">asc_mmad</a>完成矩阵乘加，结果存放在L0C Buffer。</p></li><li><p>使用<code>asc_copy_l0c2gm</code>的<a href="../cube_datamove/cube_store_key_features/NZ2ND.html">Nz2ND</a>能力，将卷积结果输出为NHWC。维度映射见<a href="../cube_datamove/cube_store_key_features/convolution_format_conversion.html">卷积格式转换</a>。<span data-filter="950">特别地，针对Ascend 950PR&amp;950DT系列产品，还可通过<a href="../cube_datamove/cube_store_key_features/NZ2DN.html">Nz2DN</a>将卷积结果输出为NCHW格式。</span></p></li></ol><h2 id="API列表">API列表<a class="header-anchor" href="#API列表">​</a></h2><h3 id="Mmad计算">Mmad计算<a class="header-anchor" href="#Mmad计算">​</a></h3><p><strong>表2</strong> Mmad计算接口</p><table><thead><tr><th>接口名称</th><th>接口描述</th><th>最细粒度公共头文件</th></tr></thead><tbody><tr><td><a href="mmad_compute/asc_mmad.html">asc_mmad</a></td><td>完成矩阵乘加操作。</td><td><code>c_api/cube_compute/cube_compute.h</code></td></tr><tr><td><a href="mmad_compute/asc_mmad_mx.html">asc_mmad_mx</a></td><td>完成带有左右矩阵量化系数的矩阵乘加计算。</td><td><code>c_api/cube_compute/cube_compute.h</code></td></tr><tr><td><a href="mmad_compute/asc_mmad_sparse.html">asc_mmad_sparse</a></td><td>完成矩阵乘加操作，传入的左矩阵A为稀疏矩阵，右矩阵B为稠密矩阵。</td><td><code>c_api/cube_compute/cube_compute.h</code></td></tr></tbody></table><h3 id="Mmad计算辅助配置接口">Mmad计算辅助配置接口<a class="header-anchor" href="#Mmad计算辅助配置接口">​</a></h3><p><strong>表3</strong> Mmad计算辅助配置接口</p><table><thead><tr><th>接口名称</th><th>接口描述</th><th>最细粒度公共头文件</th></tr></thead><tbody><tr><td><a href="mmad_compute_aux_config/asc_disable_hf32.html">asc_disable_hf32</a></td><td>用于设置Mmad计算关闭HF32模式，设置该模式后L0A Buffer/L0B Buffer中的FP32数据在参与Mmad计算之前不做舍入处理。</td><td><code>c_api/cube_compute/cube_compute.h</code></td></tr><tr><td><a href="mmad_compute_aux_config/asc_disable_hif8.html">asc_disable_hif8</a></td><td>用于设置Mmad计算关闭HiF8模式。左矩阵A和右矩阵B均为<code>fp8_e4m3fn_t</code>类型时，数据不转换为<code>hifloat8_t</code>类型，直接以<code>fp8_e4m3fn_t</code>类型参与矩阵乘法运算。</td><td><code>c_api/cube_compute/cube_compute.h</code></td></tr><tr><td><a href="mmad_compute_aux_config/asc_enable_hf32.html">asc_enable_hf32</a></td><td>用于设置Mmad计算开启HF32模式，开启该模式后L0A Buffer/L0B Buffer中的FP32数据将在参与Mmad计算之前被舍入为HF32。</td><td><code>c_api/cube_compute/cube_compute.h</code></td></tr><tr><td><a href="mmad_compute_aux_config/asc_enable_hif8.html">asc_enable_hif8</a></td><td>开启HiF8模式。左矩阵A和右矩阵B均为<code>fp8_e4m3fn_t</code>类型时，数据参与矩阵乘法运算前转换为<code>hifloat8_t</code>类型。</td><td><code>c_api/cube_compute/cube_compute.h</code></td></tr><tr><td><a href="mmad_compute_aux_config/asc_set_hf32_round_mode.html">asc_set_hf32_round_mode</a></td><td>设置HF32模式舍入方式，该配置仅在HF32模式开启期间生效。</td><td><code>c_api/cube_compute/cube_compute.h</code></td></tr><tr><td><a href="mmad_compute_aux_config/asc_set_mmad_direction_m.html">asc_set_mmad_direction_m</a></td><td>设置mmad计算时优先通过M/N中的M方向生成结果，然后通过N方向产生结果，M为矩阵的行，N为矩阵的列。</td><td><code>c_api/cube_compute/cube_compute.h</code></td></tr><tr><td><a href="mmad_compute_aux_config/asc_set_mmad_direction_n.html">asc_set_mmad_direction_n</a></td><td>设置mmad计算时优先通过M/N中的N方向生成结果，然后通过M方向产生结果，M为矩阵的行，N为矩阵的列。</td><td><code>c_api/cube_compute/cube_compute.h</code></td></tr></tbody></table></article></div>',1)])])}const v=c(i,[["render",s]]);export{A as __pageData,v as default};
